const NA = 6.022e23;
/* molar mass from an ASCII formula such as Ca(OH)2 or CuSO4·5H2O */
function fCount(f){ const parts = f.split('·'); const tot = {};
  parts.forEach(part => { let mult = 1; const m0 = part.match(/^(\d+)(.*)$/); if (m0){ mult = +m0[1]; part = m0[2]; }
    const st = [{}]; const re = /([A-Z][a-z]?|\(|\))(\d*)/g; let m;
    while ((m = re.exec(part))){ const n = m[2] ? +m[2] : 1;
      if (m[1] === '('){ st.push({}); } else if (m[1] === ')'){ const g = st.pop(); for (const k in g) st[st.length - 1][k] = (st[st.length - 1][k] || 0) + g[k]*n; }
      else st[st.length - 1][m[1]] = (st[st.length - 1][m[1]] || 0) + n; }
    for (const k in st[0]) tot[k] = (tot[k] || 0) + st[0][k]*mult; });
  return tot; }
function mm(f){ const c = fCount(f); let s = 0; for (const k in c) s += EL[k].M*c[k]; return s; }
