const ANI = [['Cl', 1, "chloride|chlorure|chlorid"], ['SO4', 2, "sulfate|sulfate|sulfat"], ['PO4', 3, "phosphate|phosphate|phosphat"], ['CO3', 2, "carbonate|carbonate|carbonat"], ['HCO3', 1, "hydrogen carbonate|hydrogénocarbonate|hydrogencarbonat"], ['NO3', 1, "nitrate|nitrate|nitrat"], ['OH', 1, "hydroxide|hydroxyde|hydroxid"], ['O', 2, "oxide|oxyde|oxid"]];
const gcd = (a, b) => b ? gcd(b, a % b) : a;
function saltF(c, a, nc, na){ const poly = s => s.length > 2 || /\d/.test(s) || s === 'OH' || s === 'NH4';
  const part = (s, n) => n === 1 ? s : (poly(s) ? '(' + s + ')' + n : s + n); return fsub(part(c, nc) + part(a, na)); }
function salt(c, a){ const l = c[1]*a[1]/gcd(c[1], a[1]); return saltF(c[0], a[0], l/c[1], l/a[1]); }
const saltName = (c, a) => [0, 1, 2].map(i => i === 1 ? sxL(a[2], 1) + ' de ' + sxL(c[2], 1) : i === 2 ? sxL(c[2], 2) + sxL(a[2], 2) : sxL(c[2], 0) + ' ' + sxL(a[2], 0)).join('|');
const OXS = [['S', 'H2SO4', 6], ['Mn', 'KMnO4', 7], ['Cr', 'K2Cr2O7', 6], ['N', 'NH3', -3], ['N', 'HNO3', 5], ['C', 'CO2', 4], ['C', 'CH4', -4], ['Fe', 'Fe2O3', 3], ['O', 'H2O2', -1], ['N', 'NO2', 4], ['S', 'H2S', -2], ['P', 'H3PO4', 5], ['Cl', 'NaClO', 1], ['C', 'CH2O', 0], ['Cu', 'Cu2O', 1], ['N', 'N2', 0]];
